-- Fundação recuperada do projeto Fidelidade.
-- Criada a partir dos contratos realmente usados pela aplicação em 10/09/2026.
-- Execute antes das migrações 20260902+ em um projeto Supabase vazio.

begin;

create table if not exists public.base_clientes_saipos (id bigint generated by default as identity primary key, nome text not null default 'Cliente', email text unique, telefone text not null unique, cpf text unique, pin_hash text, data_nascimento date, nivel text not null default 'bronze', pontos integer not null default 0, cashback numeric(12,2) not null default 0, tickets integer not null default 0, total_gasto numeric(12,2) not null default 0, qtd_pedidos integer not null default 0, primeira_compra timestamptz, ultima_compra timestamptz, origem text, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.produtos_loja (id bigint generated by default as identity primary key, nome text not null, descricao text, imagem_url text, custo_em_pontos integer not null check (custo_em_pontos > 0), categoria text not null default 'geral', destaque boolean not null default false, ativo boolean not null default false, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.premios_roleta (id bigint generated by default as identity primary key, nome text not null, descricao_vitoria text, emoji text, cor text not null default '#2563eb', probabilidade integer not null default 0 check (probabilidade >= 0), tipo text not null default 'produto', valor_pontos integer not null default 0 check (valor_pontos >= 0), valor numeric(12,2) not null default 0 check (valor >= 0), ativo boolean not null default true, created_at timestamptz not null default now(), criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.garcons (id bigint generated by default as identity primary key, nome text not null, codigo_prefixo text not null unique check (codigo_prefixo ~ '^\\d{2}$'), total_giros integer not null default 0, ativo boolean not null default true, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.garcons_logs (id bigint generated by default as identity primary key, garcom_id bigint references public.garcons(id) on delete set null, telefone_cliente text, premio text, ip text, user_agent text, score integer not null default 0, suspeito boolean not null default false, motivo text, criado_em timestamptz not null default now());
create table if not exists public.extrato_pontos (id bigint generated by default as identity primary key, cliente_id bigint not null references public.base_clientes_saipos(id) on delete cascade, tipo text not null check (tipo in ('entrada','saida')), valor numeric(12,2) not null, origem text, descricao text, metodo text, criado_em timestamptz not null default now());
create table if not exists public.saipos_pedidos_processados (id bigint generated by default as identity primary key, id_sale bigint not null unique, criado_em timestamptz not null default now());
create table if not exists public.saipos_cron_logs (id bigint generated by default as identity primary key, tipo text not null, mensagem text not null, id_cliente bigint references public.base_clientes_saipos(id) on delete set null, id_sale bigint, valor numeric(12,2), criado_em timestamptz not null default now());
create table if not exists public.resgates (id bigint generated by default as identity primary key, telefone text not null, tipo text not null, valor numeric(12,2) not null, premio_nome text not null, codigo text not null unique, status text not null default 'processado', produto_id bigint references public.produtos_loja(id) on delete set null, criado_em timestamptz not null default now(), concluido_em timestamptz);
create table if not exists public.sorteios (id uuid primary key default gen_random_uuid(), id_new bigint generated by default as identity unique, titulo text not null, descricao text, imagem_url text, data_sorteio timestamptz not null, modo text not null default 'manual' check (modo in ('manual','automatico')), status text not null default 'criado', criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
create table if not exists public.sorteios_ganhadores (id bigint generated by default as identity primary key, sorteio_id bigint not null references public.sorteios(id_new) on delete cascade, cliente_id bigint references public.base_clientes_saipos(id) on delete set null, premio text, criado_em timestamptz not null default now());
create table if not exists public.sorteios_logs (id bigint generated by default as identity primary key, sorteio_id bigint references public.sorteios(id_new) on delete cascade, mensagem text not null, detalhes jsonb not null default '{}'::jsonb, criado_em timestamptz not null default now());
create table if not exists public.sorteios_eventos (id bigint generated by default as identity primary key, sorteio_id bigint references public.sorteios(id_new) on delete cascade, tipo text not null, detalhes jsonb not null default '{}'::jsonb, criado_em timestamptz not null default now());
create table if not exists public.historico_roleta (id bigint generated by default as identity primary key, cliente_id bigint references public.base_clientes_saipos(id) on delete set null, garcom_id bigint references public.garcons(id) on delete set null, premio_id bigint references public.premios_roleta(id) on delete set null, premio text, criado_em timestamptz not null default now());
create table if not exists public.creditos_qr (id bigint generated by default as identity primary key, cliente_id bigint references public.base_clientes_saipos(id) on delete set null, codigo text unique, valor numeric(12,2), usado_em timestamptz, criado_em timestamptz not null default now());
create table if not exists public.cupons_resgatados (id bigint generated by default as identity primary key, cliente_id bigint references public.base_clientes_saipos(id) on delete set null, codigo text not null unique, criado_em timestamptz not null default now());
create index if not exists base_clientes_telefone_idx on public.base_clientes_saipos(telefone);
create index if not exists extrato_pontos_cliente_idx on public.extrato_pontos(cliente_id, criado_em desc);
create index if not exists resgates_telefone_idx on public.resgates(telefone, criado_em desc);
commit;
